variables = execution.get("variables") or {}
context = {
    "inputs": execution.get("inputs") or {},
    "vars": variables,
    "execution": {"id": execution["id"], "mode": execution["mode"]},
    "steps": {},
}

# A declared variable and a node output_var are addressable by their own
# name, which is how every playbook in this codebase is written and what
# the validator checks against. They are promoted rather than aliased so
# that {{ vars.x }} keeps working too.
for name, value in variables.items():
    # Never over a built-in scope: a variable called "alert" that hid the
    # alert would be a very quiet way to break a playbook.
    if name not in context:
        context[name] = value

for row in db.query(
    "SELECT node_id, output FROM execution_step "
    "WHERE execution_id = %s AND status = 'succeeded'",
    [execution["id"]], org_id,
):
    context["steps"][row["node_id"]] = {"output": row["output"]}

if execution.get("incident_id"):
    rows = db.query(
        "SELECT id, number, title, severity, status, technique_ids "
        "FROM incident WHERE id = %s", [execution["incident_id"]], org_id,
    )
    if rows:
        context["incident"] = rows[0]
return context
